<template>
 <div v-if="notice" class="household-notice" role="status">{{ notice }}</div>
 <footer class="persistent-player" aria-label="Household playback">
  <div class="player-copy"><strong>{{ transport?.title || (listening?.session?.player_id === selected?.player_id ? listening?.session?.title : selected?.name || 'Choose your audio') }}</strong><span>{{ session?.owner ? session.owner+' · ':'' }}{{ selected?.state || 'Choose a speaker' }}</span></div>
  <div class="transport"><button :disabled="pending || !canTransport('play')" @click="transportAction('play')" aria-label="Resume">▶</button><button :disabled="pending || !canTransport('pause')" @click="transportAction('pause')">Pause</button><button :disabled="pending || !canTransport('stop')" @click="transportAction('stop')">Stop</button><button :disabled="pending || !canTransport('next')" @click="transportAction('next')">Next</button></div>
  <button class="outputs" @click="drawer=!drawer">{{ selected?.name || 'Choose speakers' }} <span>Speakers · queue · timer</span></button>
 </footer>
 <section v-if="drawer" class="household-drawer" aria-label="Speakers and queue">
  <header><h2>Listening around the house</h2><button @click="drawer=false" aria-label="Close speakers and queue">Close</button></header>
  <p>Changing profile or selecting speakers does not interrupt playback.</p>
  <div class="speaker-choices"><label v-for="room in listening?.players || []" :key="room.entity_id"><input type="checkbox" :checked="speakers.includes(room.entity_id)" :disabled="pending || !!groupChange || !selectable(room)" @change="toggle(room.entity_id)"><strong>{{ room.name }}</strong><span>{{ !room.available?'Unavailable':!selectable(room)?'Cannot synchronise with this leader':room.state }}</span></label></div>
  <p v-if="speakers.length>1 && !transport?.actions?.length">Choose media and press Play to review a start on these idle speakers. One native group and one playback session will be used.</p><p v-if="speakers.length>1" role="status">{{ listening?.grouping?.reason || 'Grouped playback is not implemented in the household service yet. Choose one speaker; separate unsynchronised streams will not be started.' }}</p>
  <button :disabled="pending || speakers.length!==1" @click="useSpeaker">Use selected speaker</button>
  <label v-if="speakers.length>1">Session leader<select aria-label="Session leader" :value="player" :disabled="pending || !!groupChange" @change="speakerSelectionDirty=true;player=($event.target as HTMLSelectElement).value"><option v-for="room in selectedRooms" :key="room.entity_id" :value="room.entity_id" :disabled="!!room.group_parent">{{room.name}}</option></select></label>
  <button v-if="speakers.length>1 || selected?.managed_group" :disabled="pending || !selected?.features?.includes('set_members') || !!groupChange" @click="action('group_prepare',{settings:{members:speakers}})">Review speaker group</button>
  <section v-if="groupChange" aria-label="Speaker group review"><p>{{groupChange.members.join(' + ')}}</p><p v-if="groupChange.start">Start {{groupChange.start.title}} on these speakers. Existing audio will not be replaced.</p><template v-if="groupChange.phase==='prepared'"><p v-if="groupChange.removed?.length">Speakers leaving: {{groupChange.removed.join(', ')}}</p><p v-if="groupChange.occupied.length">Audio will be replaced in: {{groupChange.occupied.join(', ')}}</p><label v-if="groupChange.occupied.length"><input type="checkbox" v-model="replaceAudio">Replace audio in these occupied speakers</label><button :disabled="pending || (groupChange.occupied.length>0 && !replaceAudio)" @click="groupAction('group_confirm',{confirmation:groupChange.confirmation,...(replaceAudio?{value:'replace'}:{})})">{{groupChange.start?'Confirm group and play':'Confirm speaker group'}}</button><button :disabled="pending" @click="groupAction('group_cancel')">Cancel group change</button></template><template v-else><p>Membership is not confirmed. No grouping command will be retried automatically.</p><button :disabled="pending" @click="groupAction('group_recheck')">Recheck speaker group</button></template></section>
  <p v-if="session?.owner">{{ session.owner }} owns this queue. {{ session.joined?'You have joined listening.':'' }}</p>
  <div v-if="transport?.actions?.length" class="drawer-transport"><button :disabled="pending || !canTransport('play')" @click="transportAction('play')">Resume</button><button :disabled="pending || !canTransport('pause')" @click="transportAction('pause')">Pause</button><button :disabled="pending || !canTransport('stop')" @click="transportAction('stop')">Stop</button><button :disabled="pending || !canTransport('next')" @click="transportAction('next')">Next</button></div>
  <button v-if="session?.can_join" :disabled="pending" @click="action('queue_join',{session:session.revision})">Join listening</button>
  <button v-if="session?.can_takeover && !listening?.takeover" :disabled="pending" @click="action('queue_takeover_prepare',{session:session.revision})">Review takeover</button>
  <div v-if="listening?.takeover"><p>Take over this queue? Its contents stay; its sleep timer will be cleared. Personal progress stays separate.</p><button :disabled="pending" @click="action('queue_takeover',{session:session?.revision,confirmation:listening.takeover.confirmation})">Confirm takeover</button><button @click="action('queue_takeover_cancel')">Cancel</button></div>
  <p v-if="transport?.issue">{{ transport.issue }}</p>
  <p v-if="session?.issue || session?.edit_issue">{{ session.issue || session.edit_issue }}</p>
  <form v-if="canTransport('volume')" @submit.prevent="transportAction('volume',{value:volume})"><label>Volume (%)<input type="number" min="0" max="100" required v-model.number="volume"></label><button :disabled="pending">Apply volume</button></form>
  <label v-if="session?.owned">Sleep timer<select aria-label="Sleep timer" :disabled="pending" @change="action('sleep',{value:Number(($event.target as HTMLSelectElement).value)})"><option value="" disabled selected>Choose timer</option><option value="0">Off</option><option value="900">15 minutes</option><option value="1800">30 minutes</option><option value="3600">1 hour</option></select></label>
  <p v-if="listening?.sleep">A sleep timer is active for this session.</p>
  <ol aria-label="Selected room queue"><li v-for="row in session?.queue || []" :key="row.entry"><span>{{ row.title }}{{ row.current?' · playing':'' }}</span><button v-if="session.can_edit" :disabled="pending || !row.up" @click="action('queue_move',{entry:row.entry,value:-1,session:session.revision})">Up</button><button v-if="session.can_edit" :disabled="pending || !row.down" @click="action('queue_move',{entry:row.entry,value:1,session:session.revision})">Down</button><button v-if="session.can_edit" :disabled="pending || !row.remove" @click="action('queue_remove',{entry:row.entry,session:session.revision})">Remove</button></li></ol>
  <p v-if="!listening">Loading permitted household playback…</p>
 </section>
</template>
<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import {listening,player,speakers,notice,pending,drawer,speakerSelectionDirty,selected,session,transport,canTransport,transportAction,action} from './household';
const volume=ref<number|undefined>();
const groupChange=computed(()=>listening.value?.grouping?.pending),replaceAudio=ref(false);
const selectedRooms=computed(()=>listening.value?.players?.filter((r:any)=>speakers.value.includes(r.entity_id))||[]);
watch(()=>groupChange.value?.confirmation,()=>{replaceAudio.value=false;});
function selectable(room:any){if(!room.available)return false;if(speakers.value.includes(room.entity_id))return true;if(room.group_parent && room.group_parent!==selected.value?.player_id)return false;if(!selected.value||room.entity_id===player.value)return !!room.single;return !!selected.value.features?.includes('set_members') && selected.value.can_group_with?.includes(room.player_id) && room.can_group_with?.includes(selected.value.player_id);}
function toggle(id:string){if(pending.value||groupChange.value)return;speakerSelectionDirty.value=true;if(id===player.value && speakers.value.length>1){notice.value='Keep the session leader selected; remove the other speakers to dissolve the group.';return;}speakers.value=speakers.value.includes(id)?speakers.value.filter(v=>v!==id):[...speakers.value,id];if(!player.value || !speakers.value.includes(player.value))player.value=speakers.value[0]||null;}
async function groupAction(name:string,extra:Record<string,any>={}){const target=listening.value?.players?.find((r:any)=>r.player_id===groupChange.value?.leader)?.entity_id;if(target)await action(name,extra,target);}
async function useSpeaker(){if(speakers.value.length!==1)return;player.value=speakers.value[0];await action('destination');}
</script>
